<template><div class="form-page"><el-form label-width="190px" label-position="left"><MetadataEditor :model="localForm" title="HPA 基础配置" /><el-card shadow="never"><template #header>目标与指标</template><div class="grid-five"><el-form-item label="目标 apiVersion"><el-input v-model="localForm.scaleTargetRef.apiVersion" /></el-form-item><el-form-item label="目标类型"><el-input v-model="localForm.scaleTargetRef.kind" /></el-form-item><el-form-item label="目标名称"><el-input v-model="localForm.scaleTargetRef.name" /></el-form-item><el-form-item label="最小副本数"><el-input-number v-model="localForm.minReplicas" :min="1" /></el-form-item><el-form-item label="最大副本数"><el-input-number v-model="localForm.maxReplicas" :min="1" /></el-form-item></div><ArrayEditor v-model="localForm.metrics" title="指标" :create-item="createHpaMetric"><template #default="{ item }"><div class="grid-four"><el-form-item label="类型"><el-select v-model="item.type"><el-option label="Resource" value="Resource" /><el-option label="Custom" value="Custom" /><el-option label="Pods" value="Pods" /><el-option label="Object" value="Object" /><el-option label="External" value="External" /></el-select></el-form-item><el-form-item label="资源名称"><el-input v-model="item.resourceName" /></el-form-item><el-form-item label="目标类型"><el-select v-model="item.targetType"><el-option label="Utilization" value="Utilization" /><el-option label="AverageValue" value="AverageValue" /><el-option label="Value" value="Value" /></el-select></el-form-item><el-form-item label="平均利用率"><el-input-number v-model="item.averageUtilization" :min="1" /></el-form-item><el-form-item label="平均值"><el-input v-model="item.averageValue" placeholder="500m / 1" /></el-form-item></div></template></ArrayEditor></el-card><el-card shadow="never"><template #header>行为配置</template><el-form-item label="缩容策略选择"><el-select v-model="localForm.behavior.scaleDownSelectPolicy"><el-option label="Max" value="Max" /><el-option label="Min" value="Min" /><el-option label="Disabled" value="Disabled" /></el-select></el-form-item><ArrayEditor v-model="localForm.behavior.scaleDownPolicies" title="缩容策略列表" :create-item="createHpaPolicy"><template #default="{ item }"><div class="grid-three"><el-form-item label="类型"><el-select v-model="item.type"><el-option label="Pods" value="Pods" /><el-option label="Percent" value="Percent" /></el-select></el-form-item><el-form-item label="value"><el-input-number v-model="item.value" :min="1" /></el-form-item><el-form-item label="周期秒数"><el-input-number v-model="item.periodSeconds" :min="1" /></el-form-item></div></template></ArrayEditor></el-card></el-form></div></template><script setup lang="ts">import { computed } from 'vue'; import type { HorizontalPodAutoscalerFormData } from '@/types/k8s'; import { createHpaMetric, createHpaPolicy } from '@/composables/useK8sSchema'; import MetadataEditor from '@/components/common/MetadataEditor.vue'; import ArrayEditor from '@/components/common/ArrayEditor.vue'; const props = defineProps<{ modelValue: HorizontalPodAutoscalerFormData }>(); const emit = defineEmits<{ 'update:modelValue':[value:HorizontalPodAutoscalerFormData] }>(); const localForm = computed({ get:()=>props.modelValue, set:(value:HorizontalPodAutoscalerFormData)=>emit('update:modelValue', value) });</script><style scoped>.form-page{display:grid;gap:16px}.grid-five{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.grid-four{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.grid-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}</style>
